import React, { useMemo, useState } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  fullSongList: string[];
  history: ServiceRecord[];
}

interface GroupDefinition { name: string; min: number; max: number; }

const CATEGORIES: GroupDefinition[] = [
  { name: "CLAMOR", min: 1, max: 56 },
  { name: "INVOCAÇÃO E COMUNHÃO", min: 57, max: 96 },
  { name: "DEDICAÇÃO", min: 97, max: 200 },
  { name: "MORTE, RESSURREIÇÃO E SALVAÇÃO", min: 201, max: 294 },
  { name: "CONSOLO E ENCORAJAMENTO", min: 295, max: 385 },
  { name: "SANTIFICAÇÃO E DERRAMAMENTO DO E.S.", min: 386, max: 477 },
  { name: "VOLTA DE JESUS E ETERNIDADE", min: 478, max: 571 },
  { name: "LOUVOR", min: 572, max: 649 },
  { name: "SALMOS DE LOUVOR", min: 650, max: 665 },
  { name: "GRUPO DE LOUVOR", min: 666, max: 730 },
  { name: "CORINHOS", min: 731, max: 794 },
];

const CIAS_CATEGORIES: GroupDefinition[] = [
  { name: "CLAMOR", min: 1, max: 13 },
  { name: "INVOCAÇÃO E COMUNHÃO", min: 14, max: 22 },
  { name: "DEDICAÇÃO", min: 23, max: 59 },
  { name: "MORTE, RESSURREIÇÃO E SALVAÇÃO", min: 60, max: 108 },
  { name: "CONSOLO E ENCORAJAMENTO", min: 109, max: 132 },
  { name: "SANTIFICAÇÃO E DERRAMAMENTO DO E.S.", min: 133, max: 180 },
  { name: "VOLTA DE JESUS E ETERNIDADE", min: 181, max: 219 },
  { name: "LOUVOR", min: 220, max: 241 },
];

const UnplayedList: React.FC<Props> = ({ fullSongList, history }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isPrincipaisExpanded, setIsPrincipaisExpanded] = useState(true);
  const [isCiasExpanded, setIsCiasExpanded] = useState(true);
  const [expandedSubCats, setExpandedSubCats] = useState<Record<string, boolean>>({});
  const [expandedCiasSubCats, setExpandedCiasSubCats] = useState<Record<string, boolean>>({});

  const extractNumber = (song: string): number | null => {
    const match = song.match(/(\d+)/);
    return match ? parseInt(match[1], 10) : null;
  };

  const { groupedMain, groupedCias, mainStats, ciasStats } = useMemo(() => {
    const playedSongsSet = new Set<string>();
    history.forEach(r => r.songs.forEach(s => playedSongsSet.add(s.trim())));

    const mainGroups: Record<string, string[]> = {};
    CATEGORIES.forEach(cat => mainGroups[cat.name] = []);
    const ciasGroups: Record<string, string[]> = {};
    CIAS_CATEGORIES.forEach(cat => ciasGroups[cat.name] = []);

    let unMain = 0, totMain = 0, unCias = 0, totCias = 0;

    fullSongList.forEach(song => {
      const isUnplayed = !playedSongsSet.has(song.trim());
      const isCias = song.startsWith('(CIAS)');
      if (isCias) { totCias++; if (isUnplayed) unCias++; } else { totMain++; if (isUnplayed) unMain++; }

      if (isUnplayed && song.toLowerCase().includes(searchTerm.toLowerCase())) {
        const num = extractNumber(song);
        if (isCias) {
          if (num !== null) {
            for (const cat of CIAS_CATEGORIES) if (num >= cat.min && num <= cat.max) { ciasGroups[cat.name].push(song); break; }
          }
        } else {
          if (num !== null) {
            for (const cat of CATEGORIES) if (num >= cat.min && num <= cat.max) { mainGroups[cat.name].push(song); break; }
          }
        }
      }
    });

    return { 
      groupedMain: mainGroups, groupedCias: ciasGroups,
      mainStats: { unplayed: unMain, total: totMain, percent: totMain > 0 ? ((totMain - unMain) / totMain) * 100 : 0 },
      ciasStats: { unplayed: unCias, total: totCias, percent: totCias > 0 ? ((totCias - unCias) / totCias) * 100 : 0 }
    };
  }, [fullSongList, history, searchTerm]);

  const handleShareCategory = (catName: string, songs: string[]) => {
    if (songs.length === 0) return;
    const text = `🎵 *HINOS RESTANTES (${catName})*\n\n` + songs.map(s => `▫️ ${s}`).join('\n');
    if (navigator.share) {
      navigator.share({ title: `Hinos Restantes - ${catName}`, text });
    } else {
      window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
    }
  };

  const formatPercent = (val: number) => {
    // Formata com no máximo 1 casa decimal e troca ponto por vírgula
    return val.toFixed(1).replace('.', ',');
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 px-1">
        <div>
          <h2 className="text-2xl font-black text-white flex items-center gap-3 tracking-tight">Hinos Restantes</h2>
          <p className="text-[10px] text-slate-400 font-black mt-1 uppercase tracking-[0.2em]">Incentive o ensino de novos louvores</p>
        </div>
        <div className="relative w-full md:w-80">
          <span className="material-icons absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 text-sm">search</span>
          <input 
            type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Filtrar por nome ou nº..."
            className="w-full pl-11 pr-4 py-4 bg-white border border-slate-100 rounded-2xl text-slate-900 outline-none focus:border-indigo-500 shadow-2xl text-xs font-bold placeholder:text-slate-200"
          />
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
        {[ { label: "Coletânea Principal", stats: mainStats, color: 'indigo' }, { label: "Coletânea CIAS", stats: ciasStats, color: 'emerald' } ].map(p => (
          <div key={p.label} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-xl flex flex-col sm:flex-row items-center gap-8">
            <div className="flex-1 w-full">
              <div className="flex justify-between items-end mb-3">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">{p.label}</span>
                <span className={`text-${p.color}-600 font-black text-xs`}>{formatPercent(p.stats.percent)}%</span>
              </div>
              <div className="w-full h-2.5 bg-slate-50 rounded-full overflow-hidden border border-slate-100">
                <div className={`h-full bg-${p.color}-500 transition-all duration-1000`} style={{ width: `${p.stats.percent}%` }} />
              </div>
            </div>
            <div className="flex gap-3 shrink-0">
              <div className="text-center bg-slate-50 px-4 py-2.5 rounded-2xl border border-slate-100 min-w-[70px]">
                <div className="text-lg font-black text-slate-900 leading-none">{p.stats.unplayed}</div>
                <div className="text-[7px] font-black text-slate-400 uppercase mt-1">Faltam</div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {[ { title: "Principais", stats: mainStats, groups: groupedMain, cats: CATEGORIES, color: 'indigo', state: isPrincipaisExpanded, setState: setIsPrincipaisExpanded, subState: expandedSubCats, setSubState: setExpandedSubCats },
           { title: "CIAS", stats: ciasStats, groups: groupedCias, cats: CIAS_CATEGORIES, color: 'emerald', state: isCiasExpanded, setState: setIsCiasExpanded, subState: expandedCiasSubCats, setSubState: setExpandedCiasSubCats } ].map(col => (
          <div key={col.title} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-2xl overflow-hidden flex flex-col">
            <button onClick={() => col.setState(!col.state)} className={`w-full p-8 flex justify-between items-center bg-slate-50 hover:bg-slate-100 transition-colors border-b border-slate-100`}>
              <div className="flex items-center gap-4">
                <span className={`material-icons text-${col.color}-600 transition-transform duration-300 ${col.state ? '' : '-rotate-90'}`}>keyboard_arrow_down</span>
                <h3 className={`font-black text-slate-900 uppercase tracking-[0.2em] text-xs`}>{col.title} <span className={`ml-2 text-${col.color}-600`}>({col.stats.unplayed})</span></h3>
              </div>
            </button>
            {col.state && (
              <div className="p-5 space-y-4 max-h-[60vh] overflow-y-auto custom-scrollbar">
                {col.cats.map(cat => (
                  <div key={cat.name} className="border border-slate-100 rounded-3xl overflow-hidden">
                    <div className="flex items-center">
                      <button onClick={() => col.setSubState({ ...col.subState, [cat.name]: !col.subState[cat.name] })} className={`flex-1 px-6 py-5 flex justify-between items-center transition-colors ${col.subState[cat.name] ? 'bg-slate-50' : 'hover:bg-slate-50'}`}>
                        <div className="flex flex-col items-start">
                          <span className={`text-[10px] font-black tracking-widest text-left pr-4 ${col.subState[cat.name] ? `text-${col.color}-600` : 'text-slate-500'}`}>{cat.name}</span>
                          <span className="text-[8px] font-black text-slate-300 uppercase mt-1">Restam {col.groups[cat.name].length}</span>
                        </div>
                        <span className="material-icons text-slate-200 text-xl">{col.subState[cat.name] ? 'expand_less' : 'expand_more'}</span>
                      </button>
                      {col.groups[cat.name].length > 0 && (
                        <button onClick={() => handleShareCategory(cat.name, col.groups[cat.name])} className="p-5 text-indigo-500 active:scale-90 transition-transform"><span className="material-icons">share</span></button>
                      )}
                    </div>
                    {col.subState[cat.name] && (
                      <div className="p-4 grid gap-2.5 animate-fadeIn bg-slate-50/50">
                        {col.groups[cat.name].length > 0 ? col.groups[cat.name].map((s, i) => (
                          <div key={i} className="p-4 bg-white rounded-2xl text-[11px] font-bold text-slate-700 border border-slate-100 uppercase tracking-tight shadow-sm">{s}</div>
                        )) : <p className="py-4 text-center text-[9px] font-black text-emerald-600 uppercase tracking-widest">Categoria Completa!</p>}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default UnplayedList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
  externalFilter?: { worker: string; role: string } | null;
  onClearExternalFilter?: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit, externalFilter, onClearExternalFilter }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [showShareOptions, setShowShareOptions] = useState(false);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const getSpecialBadge = (dateString: string) => {
    const d = new Date(dateString + 'T12:00:00');
    const day = d.getDay();
    if (day === 1) return { 
      label: 'Glorificação', 
      color: 'bg-indigo-600', 
      emoji: '🎤', 
      bg: 'bg-indigo-50/80', 
      border: 'border-indigo-100', 
      textColor: 'text-indigo-700' 
    };
    if (day === 3) return { 
      label: 'Senhoras', 
      color: 'bg-rose-500', 
      emoji: '🌸', 
      bg: 'bg-rose-50/80', 
      border: 'border-rose-100', 
      textColor: 'text-rose-700' 
    };
    if (day === 4) return { 
      label: 'Oração', 
      color: 'bg-amber-500', 
      emoji: '🙏', 
      bg: 'bg-amber-50/80', 
      border: 'border-amber-100', 
      textColor: 'text-amber-700' 
    };
    return null;
  };

  const groupedHistory = useMemo(() => {
    let filtered = [...history];
    if (externalFilter) {
      filtered = filtered.filter(r => r.roles[externalFilter.role as keyof typeof r.roles] === externalFilter.worker);
    }
    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      filtered = filtered.filter(r => {
        const d = new Date(r.date + 'T12:00:00');
        const badge = getSpecialBadge(r.date);
        return (
          r.date.includes(lowerSearch) ||
          r.description.toLowerCase().includes(lowerSearch) ||
          badge?.label.toLowerCase().includes(lowerSearch) ||
          Object.values(r.roles).some(v => String(v).toLowerCase().includes(lowerSearch)) ||
          r.songs.some(s => s.toLowerCase().includes(lowerSearch))
        );
      });
    }
    filtered.sort((a, b) => b.date.localeCompare(a.date));
    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm, externalFilter]);

  const generateSingleReport = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
    const badge = getSpecialBadge(r.date);
    let text = `*RELATÓRIO DE CULTO - ${dateStr} (${r.description})*\n`;
    if (badge) text = `*RELATÓRIO DE CULTO (${badge.label.toUpperCase()}) - ${dateStr}*\n`;

    if (r.roles.gate) text += `> Portão: ${r.roles.gate}\n`;
    if (r.roles.praise) text += `> Louvor: ${r.roles.praise}\n`;
    if (r.roles.word) text += `> Palavra: ${r.roles.word}\n`;
    if (r.roles.word === 'TRANSMISSÃO') {
      text += `Satélite: Transmissão\n`;
    } else if (r.roles.scripture) {
      text += `Texto: ${r.roles.scripture}\n`;
    }
    if (r.songs.length > 0) {
      text += `\nLOUVORES: \n`;
      r.songs.forEach((s, i) => { text += ` ${i + 1}. ${s}\n`; });
    }
    return text;
  };

  const handleWhatsAppShare = (title: string, records: ServiceRecord[]) => {
    // Sort ascending for the report: oldest to newest
    const reportData = [...records].sort((a, b) => a.date.localeCompare(b.date));
    const text = reportData.map(r => generateSingleReport(r)).join('\n' + '─'.repeat(15) + '\n');
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
    setShowShareOptions(false);
  };

  const handleIndividualShare = (record: ServiceRecord) => {
    const text = generateSingleReport(record);
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
  };

  const InfoTag = ({ label, value, icon, roleId }: { label: string, value?: string, icon: string, roleId: string }) => {
    if (!value) return null;
    const isHighlighted = externalFilter?.role === roleId;
    return (
      <div className={`flex flex-col border-l-2 pl-3 py-1 rounded-r-xl transition-all ${isHighlighted ? 'border-indigo-500 bg-indigo-50' : 'border-slate-200 bg-slate-50'}`}>
        <div className="flex items-center gap-1 mb-0.5">
          <span className={`material-icons text-[10px] ${isHighlighted ? 'text-indigo-600' : 'text-slate-500'}`}>{icon}</span>
          <span className={`text-[8px] font-black uppercase tracking-widest ${isHighlighted ? 'text-indigo-600' : 'text-slate-500'}`}>{label}</span>
        </div>
        <span className={`text-[11px] font-black truncate ${isHighlighted ? 'text-indigo-800' : 'text-slate-900'}`}>{value}</span>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="section-header">
        <div className="flex items-center gap-4 mb-2">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
            <span className="material-icons text-xl">history</span>
          </div>
          <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Histórico de Cultos</h2>
        </div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Consulte todos os registros anteriores</p>
      </div>

      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-2xl flex items-center px-6 py-4 shadow-xl border border-slate-100">
          <span className="material-icons text-slate-300 mr-4">search</span>
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Data, Obreiro, Hino..." className="w-full bg-transparent font-bold text-slate-900 outline-none text-sm" />
        </div>
        {history.length > 0 && (
          <button onClick={() => setShowShareOptions(true)} className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-90 shrink-0"><span className="material-icons">share</span></button>
        )}
      </div>

      {showShareOptions && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowShareOptions(false)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp max-h-[80vh] flex flex-col">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8 shrink-0"></div>
            <h3 className="text-xl font-black text-slate-900 mb-6 uppercase tracking-tighter text-center">Opções de Envio</h3>
            <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
              <button onClick={() => handleWhatsAppShare("HISTÓRICO COMPLETO", history)} className="w-full p-6 bg-indigo-600 text-white rounded-3xl flex items-center justify-between shadow-xl active:scale-[0.98]">
                <span className="font-black text-xs uppercase tracking-widest">Enviar Todo o Histórico</span>
                <span className="material-icons">history</span>
              </button>
              <div className="pt-4 pb-2"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Por Mês</span></div>
              {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
                <button key={month} onClick={() => handleWhatsAppShare(month, records)} className="w-full p-5 bg-slate-50 border border-slate-100 text-slate-700 rounded-2xl flex items-center justify-between active:scale-[0.98]">
                  <span className="font-bold text-sm">{month}</span>
                  <div className="flex items-center gap-2"><span className="text-[10px] font-black text-slate-400">{records.length} cultos</span><span className="material-icons text-emerald-500">whatsapp</span></div>
                </button>
              ))}
            </div>
            <button onClick={() => setShowShareOptions(false)} className="mt-6 w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">FECHAR</button>
          </div>
        </div>
      )}

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-5">
          <div className="px-2 flex justify-between items-center"><h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">{month}</h3></div>
          <div className="grid gap-5">
            {records.map(record => {
              const badge = getSpecialBadge(record.date);
              return (
                <div key={record.id} className="card-main p-6 md:p-10">
                  <div className="flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                      <div className="flex items-center gap-5">
                        <div className="w-14 h-14 bg-slate-50 rounded-2xl flex flex-col items-center justify-center border border-slate-100 shrink-0">
                          <span className="text-sm font-black text-indigo-600 leading-none">{new Date(record.date + 'T12:00:00').getDate()}</span>
                          <span className="text-[9px] font-bold text-slate-400 uppercase">{dayOfWeekNamesShort[new Date(record.date + 'T12:00:00').getDay()]}</span>
                        </div>
                        <div className="min-w-0">
                          <h4 className="font-black text-slate-900 uppercase text-base tracking-tight truncate">{record.description}</h4>
                          <div className="flex items-center gap-2 mt-1"><span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{record.songs.length} LOUVORES</p></div>
