                      </div>
                    </div>

                    {/* FAIXA NO HISTÓRICO */}
                    {badge && (
                      <div className={`w-full py-2.5 px-4 ${badge.bg} ${badge.border} border rounded-xl flex items-center gap-2.5 shadow-sm`}>
