                      </div>
                    )}

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                      <InfoTag label="Portão" value={record.roles.gate} icon="door_front" roleId="gate" />
                      <InfoTag label="Louvor" value={record.roles.praise} icon="music_note" roleId="praise" />
                      <InfoTag label="Palavra" value={record.roles.word} icon="record_voice_over" roleId="word" />
                      <InfoTag label="Texto" value={record.roles.word === 'TRANSMISSÃO' ? 'SATÉLITE' : record.roles.scripture} icon="auto_stories" roleId="scripture" />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
      {itemToDelete && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setItemToDelete(null)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp">
            <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter text-center">Apagar Registro?</h3>
            <div className="w-full flex flex-col gap-3 mt-6">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-500 text-white font-black rounded-3xl shadow-xl">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px]">CANCELAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
  externalFilter?: { worker: string; role: string } | null;
  onClearExternalFilter?: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit, externalFilter, onClearExternalFilter }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [showShareOptions, setShowShareOptions] = useState(false);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const getSpecialBadge = (dateString: string) => {
    const d = new Date(dateString + 'T12:00:00');
    const day = d.getDay();
    if (day === 1) return { 
      label: 'Glorificação', 
      color: 'bg-indigo-600', 
      emoji: '🎤', 
      bg: 'bg-indigo-50/80', 
      border: 'border-indigo-100', 
      textColor: 'text-indigo-700' 
    };
    if (day === 3) return { 
      label: 'Senhoras', 
      color: 'bg-rose-500', 
      emoji: '🌸', 
      bg: 'bg-rose-50/80', 
      border: 'border-rose-100', 
      textColor: 'text-rose-700' 
    };
    if (day === 4) return { 
      label: 'Oração', 
      color: 'bg-amber-500', 
      emoji: '🙏', 
      bg: 'bg-amber-50/80', 
      border: 'border-amber-100', 
      textColor: 'text-amber-700' 
    };
    return null;
  };

  const groupedHistory = useMemo(() => {
    let filtered = [...history];
    if (externalFilter) {
      filtered = filtered.filter(r => r.roles[externalFilter.role as keyof typeof r.roles] === externalFilter.worker);
    }
    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      filtered = filtered.filter(r => {
        const badge = getSpecialBadge(r.date);
        return (
          r.date.includes(lowerSearch) ||
          r.description.toLowerCase().includes(lowerSearch) ||
          badge?.label.toLowerCase().includes(lowerSearch) ||
          Object.values(r.roles).some(v => String(v).toLowerCase().includes(lowerSearch)) ||
          r.songs.some(s => s.toLowerCase().includes(lowerSearch))
        );
      });
    }
    filtered.sort((a, b) => b.date.localeCompare(a.date));
    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm, externalFilter]);

  const generateSingleReport = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
    const badge = getSpecialBadge(r.date);
    let text = `*RELATÓRIO DE CULTO - ${dateStr} (${r.description})*\n`;
    if (badge) text = `*RELATÓRIO DE CULTO (${badge.label.toUpperCase()}) - ${dateStr}*\n`;

    if (r.roles.gate) text += `> Portão: ${r.roles.gate}\n`;
    if (r.roles.praise) text += `> Louvor: ${r.roles.praise}\n`;
    if (r.roles.word) text += `> Palavra: ${r.roles.word}\n`;
    if (r.roles.word === 'TRANSMISSÃO') {
      text += `Satélite: Transmissão\n`;
    } else if (r.roles.scripture) {
      text += `Texto: ${r.roles.scripture}\n`;
    }
    if (r.songs.length > 0) {
      text += `\nLOUVORES: \n`;
      r.songs.forEach((s, i) => { text += ` ${i + 1}. ${s}\n`; });
    }
    return text;
  };

  const handleWhatsAppShare = (title: string, records: ServiceRecord[]) => {
    const reportData = [...records].sort((a, b) => a.date.localeCompare(b.date));
    const text = reportData.map(r => generateSingleReport(r)).join('\n' + '─'.repeat(15) + '\n');
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
    setShowShareOptions(false);
  };

  const handleIndividualShare = (record: ServiceRecord) => {
    const text = generateSingleReport(record);
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
  };

  const InfoTag = ({ label, value, icon, roleId }: { label: string, value?: string, icon: string, roleId: string }) => {
    if (!value) return null;
    const isHighlighted = externalFilter?.role === roleId;
    return (
      <div className={`flex flex-col border-l-2 pl-3 py-1 rounded-r-xl transition-all ${isHighlighted ? 'border-indigo-500 bg-indigo-50' : 'border-slate-200 bg-slate-50'}`}>
        <div className="flex items-center gap-1 mb-0.5">
          <span className={`material-icons text-[10px] ${isHighlighted ? 'text-indigo-600' : 'text-slate-500'}`}>{icon}</span>
          <span className={`text-[8px] font-black uppercase tracking-widest ${isHighlighted ? 'text-indigo-600' : 'text-slate-500'}`}>{label}</span>
        </div>
        <span className={`text-[11px] font-black truncate ${isHighlighted ? 'text-indigo-800' : 'text-slate-900'}`}>{value}</span>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="section-header">
        <div className="flex items-center gap-4 mb-2">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
            <span className="material-icons text-xl">history</span>
          </div>
          <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Histórico de Cultos</h2>
        </div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Consulte todos os registros anteriores</p>
      </div>

      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-2xl flex items-center px-6 py-4 shadow-xl border border-slate-100">
          <span className="material-icons text-slate-300 mr-4">search</span>
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Data, Obreiro, Hino..." className="w-full bg-transparent font-bold text-slate-900 outline-none text-sm" />
        </div>
        {history.length > 0 && (
          <button onClick={() => setShowShareOptions(true)} className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-90 shrink-0"><span className="material-icons">share</span></button>
        )}
      </div>

      {showShareOptions && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowShareOptions(false)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp max-h-[80vh] flex flex-col">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8 shrink-0"></div>
            <h3 className="text-xl font-black text-slate-900 mb-6 uppercase tracking-tighter text-center">Opções de Envio</h3>
            <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
              <button onClick={() => handleWhatsAppShare("HISTÓRICO COMPLETO", history)} className="w-full p-6 bg-indigo-600 text-white rounded-3xl flex items-center justify-between shadow-xl active:scale-[0.98]">
                <span className="font-black text-xs uppercase tracking-widest">Enviar Todo o Histórico</span>
                <span className="material-icons">history</span>
              </button>
              <div className="pt-4 pb-2"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Por Mês</span></div>
              {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
                <button key={month} onClick={() => handleWhatsAppShare(month, records)} className="w-full p-5 bg-slate-50 border border-slate-100 text-slate-700 rounded-2xl flex items-center justify-between active:scale-[0.98]">
                  <span className="font-bold text-sm">{month}</span>
                  <div className="flex items-center gap-2"><span className="text-[10px] font-black text-slate-400">{records.length} cultos</span><span className="material-icons text-emerald-500">whatsapp</span></div>
                </button>
              ))}
            </div>
            <button onClick={() => setShowShareOptions(false)} className="mt-6 w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">FECHAR</button>
          </div>
        </div>
      )}

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-5">
          <div className="px-2 flex justify-between items-center"><h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">{month}</h3></div>
          <div className="grid gap-5">
            {records.map(record => {
              const badge = getSpecialBadge(record.date);
              return (
                <div key={record.id} className="card-main p-6 md:p-10">
                  <div className="flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                      <div className="flex items-center gap-5">
                        <div className="w-14 h-14 bg-slate-50 rounded-2xl flex flex-col items-center justify-center border border-slate-100 shrink-0">
                          <span className="text-sm font-black text-indigo-600 leading-none">{new Date(record.date + 'T12:00:00').getDate()}</span>
                          <span className="text-[9px] font-bold text-slate-400 uppercase">{dayOfWeekNamesShort[new Date(record.date + 'T12:00:00').getDay()]}</span>
                        </div>
                        <div className="min-w-0">
                          <h4 className="font-black text-slate-900 uppercase text-base tracking-tight truncate">{record.description}</h4>
                          <div className="flex items-center gap-2 mt-1"><span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{record.songs.length} LOUVORES</p></div>
                        </div>
                      </div>
                      <div className="flex items-center gap-2.5 justify-end">
                        <button onClick={() => handleIndividualShare(record)} className="w-11 h-11 flex items-center justify-center text-emerald-600 bg-emerald-50 rounded-2xl active:scale-90"><span className="material-icons text-xl">share</span></button>
                        <button onClick={() => onEdit(record)} className="w-11 h-11 flex items-center justify-center text-indigo-600 bg-indigo-50 rounded-2xl active:scale-90"><span className="material-icons text-xl">edit</span></button>
                        <button onClick={() => setItemToDelete(record.id)} className="w-11 h-11 flex items-center justify-center text-rose-500 bg-rose-50 rounded-2xl active:scale-90"><span className="material-icons text-xl">delete_outline</span></button>
                      </div>
                    </div>

                    {/* FAIXA NO HISTÓRICO */}
                    {badge && (
                      <div className={`w-full py-2.5 px-4 ${badge.bg} ${badge.border} border rounded-xl flex items-center gap-2.5 shadow-sm`}>
                        <span className="text-base leading-none">{badge.emoji}</span>
                        <span className={`text-[9px] font-black uppercase tracking-[0.2em] ${badge.textColor}`}>Culto de {badge.label}</span>
                      </div>
                    )}

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                      <InfoTag label="Portão" value={record.roles.gate} icon="door_front" roleId="gate" />
                      <InfoTag label="Louvor" value={record.roles.praise} icon="music_note" roleId="praise" />
                      <InfoTag label="Palavra" value={record.roles.word} icon="record_voice_over" roleId="word" />
                      <InfoTag label="Texto" value={record.roles.word === 'TRANSMISSÃO' ? 'SATÉLITE' : record.roles.scripture} icon="auto_stories" roleId="scripture" />
                    </div>

                    {/* LISTAGEM DE LOUVORES NO CARD */}
                    {record.songs.length > 0 && (
                      <div className="mt-2 pt-5 border-t border-slate-50">
                        <span className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em] block mb-3">Louvores do Culto</span>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-2">
                          {record.songs.map((song, i) => (
                            <div key={i} className="flex items-center gap-3">
                              <span className="text-[10px] font-black text-indigo-300">{(i + 1).toString().padStart(2, '0')}</span>
                              <span className="text-[11px] font-bold text-slate-600 truncate uppercase">{song}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
      {itemToDelete && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setItemToDelete(null)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp">
            <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter text-center">Apagar Registro?</h3>
            <div className="w-full flex flex-col gap-3 mt-6">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-500 text-white font-black rounded-3xl shadow-xl">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px]">CANCELAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-200 rounded-2xl px-4 py-1 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-500/50 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    let specialName = null;
    let specialColor = '';
    let specialEmoji = '';
    let specialBg = '';
    let specialBorder = '';
    let specialTextColor = '';

    if (dayIndex === 1) { 
      specialName = 'Glorificação'; 
      specialColor = 'bg-indigo-600'; 
      specialEmoji = '🎤';
      specialBg = 'bg-indigo-50/80';
      specialBorder = 'border-indigo-100';
      specialTextColor = 'text-indigo-700';
    }
    else if (dayIndex === 3) { 
      specialName = 'Senhoras'; 
      specialColor = 'bg-rose-500'; 
      specialEmoji = '🌸';
      specialBg = 'bg-rose-50/80';
      specialBorder = 'border-rose-100';
      specialTextColor = 'text-rose-700';
    }
    else if (dayIndex === 4) { 
      specialName = 'Oração'; 
      specialColor = 'bg-amber-500'; 
      specialEmoji = '🙏';
      specialBg = 'bg-amber-50/80';
      specialBorder = 'border-amber-100';
      specialTextColor = 'text-amber-700';
    }

    return { 
      name: dayOfWeekNames[dayIndex], 
      fullName: fullDayNames[dayIndex], 
      isSunday: dayIndex === 0, 
      isMonday: dayIndex === 1,
      isWednesday: dayIndex === 3,
      isThursday: dayIndex === 4,
      specialName,
      specialColor,
      specialEmoji,
      specialBg,
      specialBorder,
      specialTextColor
    };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleShareHinosOnly = () => {
    if (draft.songs.length === 0) return;
    const d = new Date(draft.date + 'T12:00:00');
    const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
    const text = `🎶 *LISTA DE LOUVORES - ${dateStr}*\n` + 
      draft.songs.map((s, i) => `${i + 1}. ${s}`).join('\n');
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
  };

  const handleSave = () => {
    let finalDraft = { ...draft };
    if (dateInfo.isThursday) {
      finalDraft.roles.word = finalDraft.roles.praise;
    }
    onSave(finalDraft);
    setShowSuccessModal(true);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 1) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const isCiasA = a.startsWith('(CIAS)');
        const isCiasB = b.startsWith('(CIAS)');
        if (isCiasA !== isCiasB) return isCiasA ? 1 : -1;
        return a.localeCompare(b, undefined, { numeric: true });
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  const onDragStart = (item: string, index: number) => setDraggedIndex(index);
  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  return (
    <>
      {showSuccessModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm animate-fadeIn" onClick={() => setShowSuccessModal(false)} />
          <div className="relative bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center border border-slate-100">
            <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6 text-white shadow-lg shadow-emerald-500/20">
              <span className="material-icons text-3xl">check</span>
            </div>
            <h3 className="text-xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Relatório Salvo!</h3>
            <p className="text-slate-500 font-bold text-[10px] uppercase tracking-[0.2em] mb-10">Sincronizado na nuvem.</p>
            <button onClick={() => setShowSuccessModal(false)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl active:scale-95 transition-all uppercase text-xs tracking-widest">OK, CONTINUAR</button>
          </div>
        </div>
      )}

      <div className="space-y-6 animate-fadeIn pb-20">
        <div className="section-header">
          <div className="flex items-center gap-4 mb-2">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <span className="material-icons text-xl">{editingId ? 'edit' : 'add_circle'}</span>
            </div>
            <h2 className="text-2xl font-black text-white uppercase tracking-tighter">{editingId ? 'Editar Relatório' : 'Novo Relatório'}</h2>
          </div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preencha os dados do culto</p>
        </div>

        <div className="card-main p-8 md:p-12">
          <div className="space-y-8">
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input type="date" value={draft.date} onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} className="w-full bg-transparent font-black text-lg text-slate-900 text-center outline-none py-2" />
                </FormInput>
                <div className="mt-3 flex flex-wrap gap-2 justify-center">
                  <div className="bg-indigo-50 px-4 py-1.5 rounded-full border border-indigo-100">
                    <span className="text-indigo-600 font-black text-[9px] uppercase tracking-[0.2em]">dia: {dateInfo.name}</span>
                  </div>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-200 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            <div className="space-y-4 pt-8 border-t border-slate-100">
              <div className="flex justify-between items-center">
                <Label>Hinos do Culto</Label>
                {draft.songs.length > 0 && (
                  <button onClick={handleShareHinosOnly} className="text-emerald-600 font-black text-[10px] uppercase tracking-widest flex items-center gap-1.5 mb-2 active:scale-95 bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
                    <span className="material-icons text-sm">whatsapp</span>
                    Enviar Lista
                  </button>
                )}
              </div>
              <div className="flex gap-2">
                <input type="text" value={inputValue} onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} className="flex-1 px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-sm text-slate-900 outline-none focus:bg-white focus:border-indigo-500 transition-all placeholder:text-slate-300" placeholder="Hino ou Nº..." />
                <button onClick={() => checkAndAddSong(inputValue)} className="bg-indigo-600 text-white w-14 h-14 rounded-2xl flex items-center justify-center active:scale-90 shadow-lg shrink-0"><span className="material-icons text-2xl">add</span></button>
              </div>
              {showSuggestions && suggestions.length > 0 && (
                <div className="absolute z-[250] w-[calc(100%-4rem)] md:w-[calc(100%-10rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-200 max-h-60 overflow-y-auto mt-1">
                  {suggestions.map(s => (
                    <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs flex justify-between items-center transition-colors">
                      <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-slate-900'}>{s}</span>
                      <span className="material-icons text-indigo-500 text-sm">add_circle</span>
                    </div>
                  ))}
                </div>
              )}
              <div className="space-y-2 max-h-60 overflow-y-auto pr-1 custom-scrollbar">
                {draft.songs.map((s, i) => (
                  <div key={`${s}-${i}`} draggable onDragStart={() => onDragStart(s, i)} onDragOver={(e) => onDragOver(e, i)} className={`flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 cursor-move ${draggedIndex === i ? 'opacity-30' : ''}`}>
                    <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                    <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-slate-300 hover:text-rose-500"><span className="material-icons text-lg">close</span></button>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6 pt-8 border-t border-slate-100">
              {/* FAIXA DE IDENTIDADE DO CULTO */}
              {dateInfo.specialName && (
                <div className={`w-full py-4 px-6 ${dateInfo.specialBg} ${dateInfo.specialBorder} border rounded-2xl flex items-center justify-between shadow-sm animate-fadeIn mb-2`}>
                   <div className="flex items-center gap-3">
                     <span className="text-xl">{dateInfo.specialEmoji}</span>
                     <span className={`text-[11px] font-black uppercase tracking-[0.2em] ${dateInfo.specialTextColor}`}>Culto de {dateInfo.specialName}</span>
                   </div>
                   <div className={`w-2 h-2 rounded-full ${dateInfo.specialColor} animate-pulse`}></div>
                </div>
              )}

              <div className="flex flex-col">
                <Label>Portão</Label>
                <FormInput>
                  <select value={draft.roles.gate} onChange={e => updateRole('gate', e.target.value)} className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none cursor-pointer py-2">
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {!dateInfo.isWednesday && (
                <>
                  <div className="flex flex-col">
                    <Label>{dateInfo.isThursday ? 'Dirigente' : 'Louvor'}</Label>
                    <FormInput>
                      <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none cursor-pointer py-2">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>

                  {!dateInfo.isMonday && !dateInfo.isThursday && (
                    <div className="flex flex-col">
                      <Label>Palavra</Label>
                      <FormInput>
                        <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none cursor-pointer py-2">
                          <option value="">Selecione...</option>
                          {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                      </FormInput>
                    </div>
                  )}

                  <div className="flex flex-col">
                    {draft.roles.word === 'TRANSMISSÃO' && !dateInfo.isMonday ? (
                      <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-600"><span className="text-xl">📡</span><span className="font-black text-[10px] uppercase tracking-widest">Satélite</span></div>
                    ) : (
                      <>
                        <Label>Texto Bíblico</Label>
                        <FormInput>
                          <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none py-2 placeholder:text-slate-300" />
                        </FormInput>
                      </>
                    )}
                  </div>
                </>
              )}
            </div>

            <button onClick={handleSave} disabled={draft.songs.length === 0 && !dateInfo.isWednesday} className={`w-full py-6 rounded-3xl font-black text-sm tracking-[0.2em] transition-all active:scale-95 flex items-center justify-center gap-3 shadow-2xl ${draft.songs.length > 0 || dateInfo.isWednesday ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}>
              <span className="material-icons">save</span>
              {editingId ? 'ATUALIZAR' : 'SALVAR RELATÓRIO'}
            </button>
          </div>
        </div>
      </div>

      {pendingSong && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setPendingSong(null)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-10"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-amber-50 rounded-full flex items-center justify-center mb-6 text-amber-500 border border-amber-100"><span className="material-icons text-4xl">warning</span></div>
              <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
              <p className="text-slate-500 font-bold mb-10 text-[11px] uppercase tracking-widest">Cantado há <span className="text-amber-500">{pendingSong.diff} dias</span>. Prosseguir?</p>
              <div className="w-full flex flex-col gap-3">
                <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl active:scale-95">ADICIONAR MESMO ASSIM</button>
                <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
  externalFilter?: { worker: string; role: string } | null;
  onClearExternalFilter?: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit, externalFilter, onClearExternalFilter }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [showShareOptions, setShowShareOptions] = useState(false);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const getSpecialBadge = (dateString: string) => {
    const d = new Date(dateString + 'T12:00:00');
    const day = d.getDay();
    if (day === 1) return { 
      label: 'Glorificação', 
      color: 'bg-indigo-600', 
      emoji: '🎤', 
      bg: 'bg-indigo-50/80', 
      border: 'border-indigo-100', 
      textColor: 'text-indigo-700' 
    };
    if (day === 3) return { 
      label: 'Senhoras', 
      color: 'bg-rose-500', 
      emoji: '🌸', 
      bg: 'bg-rose-50/80', 
      border: 'border-rose-100', 
      textColor: 'text-rose-700' 
    };
    if (day === 4) return { 
      label: 'Oração', 
      color: 'bg-amber-500', 
      emoji: '🙏', 
      bg: 'bg-amber-50/80', 
      border: 'border-amber-100', 
      textColor: 'text-amber-700' 
    };
    return null;
  };

  const groupedHistory = useMemo(() => {
    let filtered = [...history];
    if (externalFilter) {
      filtered = filtered.filter(r => r.roles[externalFilter.role as keyof typeof r.roles] === externalFilter.worker);
    }
    if (searchTerm) {
      const lowerSearch = searchTerm.toLowerCase();
      filtered = filtered.filter(r => {
        const badge = getSpecialBadge(r.date);
        return (
          r.date.includes(lowerSearch) ||
          r.description.toLowerCase().includes(lowerSearch) ||
          badge?.label.toLowerCase().includes(lowerSearch) ||
          Object.values(r.roles).some(v => String(v).toLowerCase().includes(lowerSearch)) ||
          r.songs.some(s => s.toLowerCase().includes(lowerSearch))
        );
      });
    }
    filtered.sort((a, b) => b.date.localeCompare(a.date));
    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm, externalFilter]);

  const generateSingleReport = (r: ServiceRecord) => {
    const d = new Date(r.date + 'T12:00:00');
    const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
    const badge = getSpecialBadge(r.date);
    let text = `*RELATÓRIO DE CULTO - ${dateStr} (${r.description})*\n`;
    if (badge) text = `*RELATÓRIO DE CULTO (${badge.label.toUpperCase()}) - ${dateStr}*\n`;

    if (r.roles.gate) text += `> Portão: ${r.roles.gate}\n`;
    if (r.roles.praise) text += `> Louvor: ${r.roles.praise}\n`;
    if (r.roles.word) text += `> Palavra: ${r.roles.word}\n`;
    if (r.roles.word === 'TRANSMISSÃO') {
      text += `Satélite: Transmissão\n`;
    } else if (r.roles.scripture) {
      text += `Texto: ${r.roles.scripture}\n`;
    }
    if (r.songs.length > 0) {
      text += `\nLOUVORES: \n`;
      r.songs.forEach((s, i) => { text += ` ${i + 1}. ${s}\n`; });
    }
    return text;
  };

  const handleWhatsAppShare = (title: string, records: ServiceRecord[]) => {
    const reportData = [...records].sort((a, b) => a.date.localeCompare(b.date));
    const text = reportData.map(r => generateSingleReport(r)).join('\n' + '─'.repeat(15) + '\n');
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
    setShowShareOptions(false);
  };

  const handleIndividualShare = (record: ServiceRecord) => {
    const text = generateSingleReport(record);
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
  };

  const InfoTag = ({ label, value, icon, roleId }: { label: string, value?: string, icon: string, roleId: string }) => {
    if (!value) return null;
    const isHighlighted = externalFilter?.role === roleId;
    return (
      <div className={`flex flex-col border-l-2 pl-3 py-1 rounded-r-xl transition-all ${isHighlighted ? 'border-indigo-500 bg-indigo-50' : 'border-slate-200 bg-slate-50'}`}>
        <div className="flex items-center gap-1 mb-0.5">
          <span className={`material-icons text-[10px] ${isHighlighted ? 'text-indigo-600' : 'text-slate-500'}`}>{icon}</span>
          <span className={`text-[8px] font-black uppercase tracking-widest ${isHighlighted ? 'text-indigo-600' : 'text-slate-500'}`}>{label}</span>
        </div>
        <span className={`text-[11px] font-black ${isHighlighted ? 'text-indigo-800' : 'text-slate-900'}`}>{value}</span>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="section-header">
        <div className="flex items-center gap-4 mb-2">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
            <span className="material-icons text-xl">history</span>
          </div>
          <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Histórico de Cultos</h2>
        </div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Consulte todos os registros anteriores</p>
      </div>

      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-2xl flex items-center px-6 py-4 shadow-xl border border-slate-100">
          <span className="material-icons text-slate-300 mr-4">search</span>
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Data, Obreiro, Hino..." className="w-full bg-transparent font-bold text-slate-900 outline-none text-sm" />
        </div>
        {history.length > 0 && (
          <button onClick={() => setShowShareOptions(true)} className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-90 shrink-0"><span className="material-icons">share</span></button>
        )}
      </div>

      {showShareOptions && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setShowShareOptions(false)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp max-h-[80vh] flex flex-col">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-8 shrink-0"></div>
            <h3 className="text-xl font-black text-slate-900 mb-6 uppercase tracking-tighter text-center">Opções de Envio</h3>
            <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
              <button onClick={() => handleWhatsAppShare("HISTÓRICO COMPLETO", history)} className="w-full p-6 bg-indigo-600 text-white rounded-3xl flex items-center justify-between shadow-xl active:scale-[0.98]">
                <span className="font-black text-xs uppercase tracking-widest">Enviar Todo o Histórico</span>
                <span className="material-icons">history</span>
              </button>
              <div className="pt-4 pb-2"><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4">Por Mês</span></div>
              {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
                <button key={month} onClick={() => handleWhatsAppShare(month, records)} className="w-full p-5 bg-slate-50 border border-slate-100 text-slate-700 rounded-2xl flex items-center justify-between active:scale-[0.98]">
                  <span className="font-bold text-sm">{month}</span>
                  <div className="flex items-center gap-2"><span className="text-[10px] font-black text-slate-400">{records.length} cultos</span><span className="material-icons text-emerald-500">whatsapp</span></div>
                </button>
              ))}
            </div>
            <button onClick={() => setShowShareOptions(false)} className="mt-6 w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">FECHAR</button>
          </div>
        </div>
      )}

      {(Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
        <div key={month} className="space-y-5">
          <div className="px-2 flex justify-between items-center"><h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">{month}</h3></div>
          <div className="grid gap-5">
            {records.map(record => {
              const badge = getSpecialBadge(record.date);
              return (
                <div key={record.id} className="card-main p-6 md:p-10">
                  <div className="flex flex-col gap-6">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                      <div className="flex items-center gap-5">
                        <div className="w-14 h-14 bg-slate-50 rounded-2xl flex flex-col items-center justify-center border border-slate-100 shrink-0">
                          <span className="text-sm font-black text-indigo-600 leading-none">{new Date(record.date + 'T12:00:00').getDate()}</span>
                          <span className="text-[9px] font-bold text-slate-400 uppercase">{dayOfWeekNamesShort[new Date(record.date + 'T12:00:00').getDay()]}</span>
                        </div>
                        <div className="min-w-0 flex-1">
                          <h4 className="font-black text-slate-900 uppercase text-base tracking-tight">{record.description}</h4>
                          <div className="flex items-center gap-2 mt-1"><span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span><p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{record.songs.length} LOUVORES</p></div>
                        </div>
                      </div>
                      <div className="flex items-center gap-2.5 justify-end">
                        <button onClick={() => handleIndividualShare(record)} className="w-11 h-11 flex items-center justify-center text-emerald-600 bg-emerald-50 rounded-2xl active:scale-90"><span className="material-icons text-xl">share</span></button>
                        <button onClick={() => onEdit(record)} className="w-11 h-11 flex items-center justify-center text-indigo-600 bg-indigo-50 rounded-2xl active:scale-90"><span className="material-icons text-xl">edit</span></button>
                        <button onClick={() => setItemToDelete(record.id)} className="w-11 h-11 flex items-center justify-center text-rose-500 bg-rose-50 rounded-2xl active:scale-90"><span className="material-icons text-xl">delete_outline</span></button>
                      </div>
                    </div>

                    {/* FAIXA NO HISTÓRICO */}
                    {badge && (
                      <div className={`w-full py-2.5 px-4 ${badge.bg} ${badge.border} border rounded-xl flex items-center gap-2.5 shadow-sm`}>
                        <span className="text-base leading-none">{badge.emoji}</span>
                        <span className={`text-[9px] font-black uppercase tracking-[0.2em] ${badge.textColor}`}>Culto de {badge.label}</span>
                      </div>
                    )}

                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                      <InfoTag label="Portão" value={record.roles.gate} icon="door_front" roleId="gate" />
                      <InfoTag label="Louvor" value={record.roles.praise} icon="music_note" roleId="praise" />
                      <InfoTag label="Palavra" value={record.roles.word} icon="record_voice_over" roleId="word" />
                      <InfoTag label="Texto" value={record.roles.word === 'TRANSMISSÃO' ? 'SATÉLITE' : record.roles.scripture} icon="auto_stories" roleId="scripture" />
                    </div>

                    {/* LISTAGEM DE LOUVORES NO CARD - SEM TRUNCATE */}
                    {record.songs.length > 0 && (
                      <div className="mt-2 pt-5 border-t border-slate-50">
                        <span className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em] block mb-3">Louvores do Culto</span>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-3">
                          {record.songs.map((song, i) => (
                            <div key={i} className="flex items-start gap-3">
                              <span className="text-[10px] font-black text-indigo-300 mt-0.5">{(i + 1).toString().padStart(2, '0')}</span>
                              <span className="text-[11px] font-bold text-slate-600 uppercase leading-tight">{song}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
      {itemToDelete && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setItemToDelete(null)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp">
            <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter text-center">Apagar Registro?</h3>
            <div className="w-full flex flex-col gap-3 mt-6">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-500 text-white font-black rounded-3xl shadow-xl">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px]">CANCELAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-200 rounded-2xl px-4 py-1 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-500/50 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    let specialName = null;
    let specialColor = '';
    let specialEmoji = '';
    let specialBg = '';
    let specialBorder = '';
    let specialTextColor = '';

    if (dayIndex === 1) { 
      specialName = 'Glorificação'; 
      specialColor = 'bg-indigo-600'; 
      specialEmoji = '🎤';
      specialBg = 'bg-indigo-50/80';
      specialBorder = 'border-indigo-100';
      specialTextColor = 'text-indigo-700';
    }
    else if (dayIndex === 3) { 
      specialName = 'Senhoras'; 
      specialColor = 'bg-rose-500'; 
      specialEmoji = '🌸';
      specialBg = 'bg-rose-50/80';
      specialBorder = 'border-rose-100';
      specialTextColor = 'text-rose-700';
    }
    else if (dayIndex === 4) { 
      specialName = 'Oração'; 
      specialColor = 'bg-amber-500'; 
      specialEmoji = '🙏';
      specialBg = 'bg-amber-50/80';
      specialBorder = 'border-amber-100';
      specialTextColor = 'text-amber-700';
    }

    return { 
      name: dayOfWeekNames[dayIndex], 
      fullName: fullDayNames[dayIndex], 
      isSunday: dayIndex === 0, 
      isMonday: dayIndex === 1,
      isWednesday: dayIndex === 3,
      isThursday: dayIndex === 4,
      specialName,
      specialColor,
      specialEmoji,
      specialBg,
      specialBorder,
      specialTextColor
    };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleShareHinosOnly = () => {
    if (draft.songs.length === 0) return;
    const d = new Date(draft.date + 'T12:00:00');
    const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
    const text = `🎶 *LISTA DE LOUVORES - ${dateStr}*\n\n` + 
      draft.songs.map((s, i) => `${i + 1}. ${s}`).join('\n');
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
  };

  const handleSave = () => {
    let finalDraft = { ...draft };
    if (dateInfo.isThursday) {
      finalDraft.roles.word = finalDraft.roles.praise;
    }
    onSave(finalDraft);
    setShowSuccessModal(true);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 1) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const isCiasA = a.startsWith('(CIAS)');
        const isCiasB = b.startsWith('(CIAS)');
        if (isCiasA !== isCiasB) return isCiasA ? 1 : -1;
        return a.localeCompare(b, undefined, { numeric: true });
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  const onDragStart = (item: string, index: number) => setDraggedIndex(index);
  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  return (
    <>
      {showSuccessModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm animate-fadeIn" onClick={() => setShowSuccessModal(false)} />
          <div className="relative bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center border border-slate-100">
            <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6 text-white shadow-lg shadow-emerald-500/20">
              <span className="material-icons text-3xl">check</span>
            </div>
            <h3 className="text-xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Relatório Salvo!</h3>
            <p className="text-slate-500 font-bold text-[10px] uppercase tracking-[0.2em] mb-10">Sincronizado na nuvem.</p>
            <button onClick={() => setShowSuccessModal(false)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl active:scale-95 transition-all uppercase text-xs tracking-widest">OK, CONTINUAR</button>
          </div>
        </div>
      )}

      <div className="space-y-6 animate-fadeIn pb-20">
        <div className="section-header">
          <div className="flex items-center gap-4 mb-2">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <span className="material-icons text-xl">{editingId ? 'edit' : 'add_circle'}</span>
            </div>
            <h2 className="text-2xl font-black text-white uppercase tracking-tighter">{editingId ? 'Editar Relatório' : 'Novo Relatório'}</h2>
          </div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preencha os dados do culto</p>
        </div>

        <div className="card-main p-8 md:p-12">
          <div className="space-y-8">
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input type="date" value={draft.date} onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} className="w-full bg-transparent font-black text-lg text-slate-900 text-center outline-none py-2" />
                </FormInput>
                <div className="mt-3 flex flex-wrap gap-2 justify-center">
                  <div className="bg-indigo-50 px-4 py-1.5 rounded-full border border-indigo-100">
                    <span className="text-indigo-600 font-black text-[9px] uppercase tracking-[0.2em]">dia: {dateInfo.name}</span>
                  </div>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-200 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            <div className="space-y-4 pt-8 border-t border-slate-100">
              <div className="flex justify-between items-center">
                <Label>Hinos do Culto</Label>
                {draft.songs.length > 0 && (
                  <button onClick={handleShareHinosOnly} className="text-emerald-600 font-black text-[10px] uppercase tracking-widest flex items-center gap-1.5 mb-2 active:scale-95 bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
                    <span className="material-icons text-sm">whatsapp</span>
                    Enviar Lista
                  </button>
                )}
              </div>
              <div className="flex gap-2">
                <input type="text" value={inputValue} onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} className="flex-1 px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-sm text-slate-900 outline-none focus:bg-white focus:border-indigo-500 transition-all placeholder:text-slate-300" placeholder="Hino ou Nº..." />
                <button onClick={() => checkAndAddSong(inputValue)} className="bg-indigo-600 text-white w-14 h-14 rounded-2xl flex items-center justify-center active:scale-90 shadow-lg shrink-0"><span className="material-icons text-2xl">add</span></button>
              </div>
              {showSuggestions && suggestions.length > 0 && (
                <div className="absolute z-[250] w-[calc(100%-4rem)] md:w-[calc(100%-10rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-200 max-h-60 overflow-y-auto mt-1">
                  {suggestions.map(s => (
                    <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs flex justify-between items-center transition-colors">
                      <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-slate-900'}>{s}</span>
                      <span className="material-icons text-indigo-500 text-sm">add_circle</span>
                    </div>
                  ))}
                </div>
              )}
              <div className="space-y-2 max-h-60 overflow-y-auto pr-1 custom-scrollbar">
                {draft.songs.map((s, i) => (
                  <div key={`${s}-${i}`} draggable onDragStart={() => onDragStart(s, i)} onDragOver={(e) => onDragOver(e, i)} className={`flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 cursor-move ${draggedIndex === i ? 'opacity-30' : ''}`}>
                    <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                    <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-slate-300 hover:text-rose-500"><span className="material-icons text-lg">close</span></button>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-6 pt-8 border-t border-slate-100">
              {/* FAIXA DE IDENTIDADE DO CULTO */}
              {dateInfo.specialName && (
                <div className={`w-full py-4 px-6 ${dateInfo.specialBg} ${dateInfo.specialBorder} border rounded-2xl flex items-center justify-between shadow-sm animate-fadeIn mb-2`}>
                   <div className="flex items-center gap-3">
                     <span className="text-xl">{dateInfo.specialEmoji}</span>
                     <span className={`text-[11px] font-black uppercase tracking-[0.2em] ${dateInfo.specialTextColor}`}>Culto de {dateInfo.specialName}</span>
                   </div>
                   <div className={`w-2 h-2 rounded-full ${dateInfo.specialColor} animate-pulse`}></div>
                </div>
              )}

              <div className="flex flex-col">
                <Label>Portão</Label>
                <FormInput>
                  <select value={draft.roles.gate} onChange={e => updateRole('gate', e.target.value)} className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none cursor-pointer py-2">
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {!dateInfo.isWednesday && (
                <>
                  <div className="flex flex-col">
                    <Label>{dateInfo.isThursday ? 'Dirigente' : 'Louvor'}</Label>
                    <FormInput>
                      <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none cursor-pointer py-2">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>

                  {!dateInfo.isMonday && !dateInfo.isThursday && (
                    <div className="flex flex-col">
                      <Label>Palavra</Label>
                      <FormInput>
                        <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none cursor-pointer py-2">
                          <option value="">Selecione...</option>
                          {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                      </FormInput>
                    </div>
                  )}

                  <div className="flex flex-col">
                    {draft.roles.word === 'TRANSMISSÃO' && !dateInfo.isMonday ? (
                      <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-600"><span className="text-xl">📡</span><span className="font-black text-[10px] uppercase tracking-widest">Satélite</span></div>
                    ) : (
                      <>
                        <Label>Texto Bíblico</Label>
                        <FormInput>
                          <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-slate-900 text-center outline-none py-2 placeholder:text-slate-300" />
                        </FormInput>
                      </>
                    )}
                  </div>
                </>
              )}
            </div>

            <button onClick={handleSave} disabled={draft.songs.length === 0 && !dateInfo.isWednesday} className={`w-full py-6 rounded-3xl font-black text-sm tracking-[0.2em] transition-all active:scale-95 flex items-center justify-center gap-3 shadow-2xl ${draft.songs.length > 0 || dateInfo.isWednesday ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-300 cursor-not-allowed'}`}>
              <span className="material-icons">save</span>
              {editingId ? 'ATUALIZAR' : 'SALVAR RELATÓRIO'}
            </button>
          </div>
        </div>
      </div>

      {pendingSong && (
        <div className="fixed inset-0 z-[8000] flex flex-col justify-end">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setPendingSong(null)} />
          <div className="relative bg-white rounded-t-[3.5rem] p-10 pb-12 shadow-2xl animate-slideUp">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-10"></div>
            <div className="flex flex-col items-center text-center">
              <div className="w-20 h-20 bg-amber-50 rounded-full flex items-center justify-center mb-6 text-amber-500 border border-amber-100"><span className="material-icons text-4xl">warning</span></div>
              <h3 className="text-2xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
              <p className="text-slate-500 font-bold mb-10 text-[11px] uppercase tracking-widest">Cantado há <span className="text-amber-500">{pendingSong.diff} dias</span>. Prosseguir?</p>
              <div className="w-full flex flex-col gap-3">
                <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl active:scale-95">ADICIONAR MESMO ASSIM</button>
                <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">CANCELAR</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ServiceForm;

export interface ServiceRoles {
  gate: string;      // Portão
  praise: string;    // Louvor
  word: string;      // Palavra (Obreiro selecionado)
  scripture: string; // Texto Bíblico (Livro e versículo digitados)
}

export interface ServiceRecord {
  id: string;
  date: string;
  description: string; // EBD, DOM, ou Dia da Semana
  songs: string[];
  roles: ServiceRoles;
}

export interface ServiceDraft {
  date: string;
  description: string;
  songs: string[];
  roles: ServiceRoles;
}

export interface SongStats {
  song: string;
  count: number;
  lastDate: string | null;
  history: string[];
}

export type LearningStatus = 'not_started' | 'learning' | 'learned' | 'correcting';

export interface PraiseLearningItem {
  song: string;
  status: LearningStatus;
  updatedAt: string;
}

export interface AppData {
  history: ServiceRecord[];
  customSongs?: string[];
  customWorkers?: string[];
  draft?: ServiceDraft;
  learningList?: PraiseLearningItem[];
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { INITIAL_PRAISE_LIST, DEFAULT_WORKERS_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft, PraiseLearningItem } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import PraiseLearningList from './components/PraiseLearningList';
import WorkerManager from './components/WorkerManager';
import AuthForm from './components/AuthForm';
import { initDB, saveData, loadData } from './db';
import { supabase } from './supabase';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'unplayed' | 'learning' | 'praise-ranking' | 'workers' | 'suggestions' | 'manage-workers' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [customWorkers, setCustomWorkers] = useState<string[]>(DEFAULT_WORKERS_LIST);
  const [learningList, setLearningList] = useState<PraiseLearningItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadingStatus, setLoadingStatus] = useState('Iniciando sistema...');
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [user, setUser] = useState<any>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'local' | 'error'>('local');

  const [hasCheckedCloud, setHasCheckedCloud] = useState(false);
  const lastCloudUpdateRef = useRef<string | null>(null);
  const syncTimeoutRef = useRef<number | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const getSpecialServiceInfo = (dateString: string) => {
    const d = new Date(dateString + 'T12:00:00');
    const day = d.getDay();
    if (day === 1) return { name: 'Glorificação', color: 'text-indigo-400' };
    if (day === 3) return { name: 'Senhoras', color: 'text-rose-400' };
    if (day === 4) return { name: 'Oração', color: 'text-amber-400' };
    return null;
  };

  const todaySpecial = useMemo(() => getSpecialServiceInfo(getTodayDate()), []);

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  const pullFromCloud = async (userId: string) => {
    try {
      setSyncStatus('syncing');
      const { data, error } = await supabase
        .from('user_data')
        .select('json_data, updated_at')
        .eq('user_id', userId)
        .maybeSingle();

      if (error) throw error;

      if (data && data.json_data) {
        const cloudTimestamp = data.updated_at;
        if (!lastCloudUpdateRef.current || new Date(cloudTimestamp) > new Date(lastCloudUpdateRef.current)) {
          lastCloudUpdateRef.current = cloudTimestamp;
          const remote = data.json_data;
          if (remote.history) setHistory(remote.history);
          if (remote.customSongs) setCustomSongs(remote.customSongs);
          if (remote.customWorkers) setCustomWorkers(remote.customWorkers);
          if (remote.learningList) setLearningList(remote.learningList);
        }
      }
      setSyncStatus('synced');
    } catch (e) {
      console.error("Erro ao puxar dados da nuvem:", e);
      setSyncStatus('error');
    }
  };

  const pushToCloud = async () => {
    if (!user || isOffline) return;
    setSyncStatus('syncing');
    try {
      const timestamp = new Date().toISOString();
      const { error } = await supabase.from('user_data').upsert({ 
        user_id: user.id, 
        json_data: { history, customSongs, customWorkers, learningList },
        updated_at: timestamp
      }, { onConflict: 'user_id' });

      if (error) throw error;
      lastCloudUpdateRef.current = timestamp;
      setSyncStatus('synced');
    } catch (e) {
      console.error("Erro ao enviar dados para nuvem:", e);
      setSyncStatus('error');
    }
  };

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription: authSub } } = supabase.auth.onAuthStateChange((_event, session) => {
      const newUser = session?.user ?? null;
      setUser(newUser);
      if (!newUser) {
        setHasCheckedCloud(false);
        setSyncStatus('local');
        lastCloudUpdateRef.current = null;
      } else {
        setShowAuthModal(false);
      }
    });

    const setup = async () => {
      try {
        setLoadingStatus('Conectando ao banco local...');
        await initDB();

        setLoadingStatus('Recuperando seus registros...');
        const data = await loadData();

        if (data) {
          setLoadingStatus('Organizando informações...');
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.customWorkers) setCustomWorkers(data.customWorkers);
          if (data.learningList) setLearningList(data.learningList);
          if (data.draft) setDraft({ ...data.draft, date: getTodayDate() });
        }

        setLoadingStatus('Quase pronto...');
        await new Promise(r => setTimeout(r, 800));

      } catch (e) {
        console.error("Erro no DB Local", e);
        setLoadingStatus('Erro ao carregar dados locais.');
      } finally {
        setIsLoading(false);
      }
    };
    setup();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      authSub.unsubscribe();
    };
  }, []);

  useEffect(() => {
    if (!user) return;
    const channel = supabase
      .channel(`db-sync-${user.id}`)
      .on('postgres_changes', 
        { event: 'UPDATE', schema: 'public', table: 'user_data', filter: `user_id=eq.${user.id}` },
        (payload: any) => {
          if (payload.new && payload.new.updated_at !== lastCloudUpdateRef.current) {
            pullFromCloud(user.id);
          }
        }
      )
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [user]);

  useEffect(() => {
    if (user && !isLoading && !hasCheckedCloud) {
      pullFromCloud(user.id).then(() => setHasCheckedCloud(true));
    }
  }, [user, isLoading, hasCheckedCloud]);

  useEffect(() => {
    if (isLoading) return;
    saveData({ history, customSongs, customWorkers, draft, learningList });
    if (user && !isOffline && hasCheckedCloud) {
      if (syncTimeoutRef.current) window.clearTimeout(syncTimeoutRef.current);
      setSyncStatus('syncing');
      syncTimeoutRef.current = window.setTimeout(async () => {
        const { data: remoteInfo } = await supabase.from('user_data').select('updated_at').eq('user_id', user.id).maybeSingle();
        if (remoteInfo && lastCloudUpdateRef.current && new Date(remoteInfo.updated_at) > new Date(lastCloudUpdateRef.current)) {
          await pullFromCloud(user.id);
        } else {
          await pushToCloud();
        }
      }, 2000);
    } else if (!user) {
      setSyncStatus('local');
    }
  }, [history, customSongs, customWorkers, draft, learningList, user, isOffline, isLoading, hasCheckedCloud]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo Culto' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Hinos Restantes' },
    { id: 'learning', icon: 'school', label: 'Aprendizado' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Ranking Hinos' },
    { id: 'workers', icon: 'emoji_events', label: 'Ranking Obreiros' },
    { id: 'suggestions', icon: 'assignment_ind', label: 'Sugestão Escala' },
    { id: 'manage-workers', icon: 'person_add', label: 'Gerenciar Obreiros' },
    { id: 'settings', icon: 'settings', label: 'Backup / Nuvem' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0,0);
  };

  const AppBrand = () => {
    const statusIcon = { synced: 'cloud_done', syncing: 'sync', local: 'cloud_off', error: 'cloud_off' }[syncStatus];
    const statusColor = { synced: 'text-emerald-400', syncing: 'text-amber-400 animate-spin', local: 'text-slate-500', error: 'text-rose-500' }[syncStatus];
    const statusText = { synced: 'Sincronizado', syncing: 'Sincronizando...', local: 'Modo Local', error: 'Erro Conexão' }[syncStatus];

    return (
      <div className="flex items-center gap-4">
        <div className="w-12 h-12 bg-white rounded-xl shadow-xl flex items-center justify-center p-2 shrink-0">
          <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" alt="Logo" className="w-full h-full object-contain" />
        </div>
        <div className="flex flex-col min-w-0">
          <h1 className="text-white font-black text-lg tracking-tighter leading-tight uppercase whitespace-nowrap">Santo Antônio II</h1>
          <div className="flex items-center gap-2 mt-0.5">
             <div className="flex items-center gap-1.5">
               <span className={`material-icons text-[12px] ${statusColor}`}>{statusIcon}</span>
               <span className="text-slate-400 font-black text-[9px] uppercase tracking-widest">{statusText}</span>
             </div>
             <div className="h-3 w-px bg-white/10 mx-1"></div>
             <div className="flex items-center gap-1">
               <span className="material-icons text-[12px] text-amber-400">analytics</span>
               <span className="text-amber-400 font-black text-[9px] uppercase tracking-widest">{history.length} Cultos</span>
             </div>
          </div>
        </div>
      </div>
    );
  };

  const UserHeader = () => (
    <div className="p-8 border-b border-white/5 bg-white/5">
      {user ? (
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-indigo-500 rounded-2xl flex items-center justify-center shadow-lg">
            <span className="material-icons text-white">person</span>
          </div>
          <div className="flex flex-col min-w-0">
            <span className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">Conta Ativa</span>
            <span className="text-white font-black text-xs uppercase truncate leading-none">{user.email}</span>
            <button onClick={() => supabase.auth.signOut()} className="mt-2 self-start text-[8px] font-black text-rose-400 uppercase tracking-widest hover:text-rose-300">Sair da Conta</button>
          </div>
        </div>
      ) : (
        <button 
          onClick={() => setShowAuthModal(true)}
          className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] flex items-center justify-center gap-2 shadow-xl transition-all active:scale-95"
        >
          <span className="material-icons text-sm">login</span>
          Entrar p/ Sincronizar
        </button>
      )}
    </div>
  );

  if (isLoading) return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center text-white p-10 animate-fadeIn relative overflow-hidden">
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[500px] h-[500px] bg-indigo-500/10 blur-[120px] rounded-full pointer-events-none"></div>
      <div className="relative mb-12 flex flex-col items-center">
        <div className="w-24 h-24 bg-white rounded-3xl shadow-[0_20px_50px_rgba(79,70,229,0.3)] flex items-center justify-center p-4 relative z-10 animate-pulse">
          <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-full h-full object-contain" alt="Logo" />
        </div>
      </div>
      <div className="flex flex-col items-center gap-5 max-w-xs w-full relative z-10">
        <div className="text-center">
          <h2 className="font-black tracking-[0.3em] text-[10px] uppercase text-slate-400 mb-1">ICM Santo Antônio II</h2>
          <p className="text-[8px] font-black text-slate-600 uppercase tracking-[0.4em]">Gestão Eclesiástica</p>
        </div>
        <div className="w-full h-1 bg-white/5 rounded-full overflow-hidden relative">
          <div className="h-full bg-gradient-to-r from-indigo-600 to-indigo-400 w-1/2 rounded-full animate-loading-bar shadow-[0_0_10px_rgba(79,70,229,0.5)]"></div>
        </div>
        <p className="font-black tracking-[0.15em] text-[9px] uppercase text-indigo-400/80 animate-pulse h-4">{loadingStatus}</p>
      </div>
      <style>{`
        @keyframes loading-bar {
          0% { transform: translateX(-100%) scaleX(0.5); }
          50% { transform: translateX(50%) scaleX(1); }
          100% { transform: translateX(200%) scaleX(0.5); }
        }
        .animate-loading-bar { animation: loading-bar 1.8s cubic-bezier(0.65, 0, 0.35, 1) infinite; }
      `}</style>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col md:flex-row">
      <aside className="hidden md:flex w-80 bg-[#1e293b] flex-col sticky top-0 h-screen shadow-2xl z-[150] border-r border-white/5">
        <div className="p-10 border-b border-white/5">
          <AppBrand />
        </div>
        <UserHeader />
        <nav className="flex-1 py-6 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id} 
              onClick={() => handleTabChange(item.id)} 
              className={`w-full flex items-center justify-between gap-5 px-10 py-5 transition-all duration-300 border-l-4 ${activeTab === item.id ? 'bg-indigo-600/10 border-indigo-500 text-white font-black' : 'border-transparent text-slate-500 hover:text-white/60 hover:bg-white/5'}`}
            >
              <div className="flex items-center gap-5">
                <span className="material-icons text-xl">{item.icon}</span>
                <span className="text-[11px] uppercase font-black tracking-widest">{item.label}</span>
              </div>
              {item.id === 'new' && todaySpecial && (
                <div className={`flex items-center gap-1.5 ${todaySpecial.color} animate-pulse`}>
                  <span className="w-1.5 h-1.5 rounded-full bg-current"></span>
                  <span className="text-[8px] font-black uppercase tracking-tighter">{todaySpecial.name}</span>
                </div>
              )}
            </button>
          ))}
        </nav>
      </aside>

      <header className="md:hidden bg-[#1e293b] text-white p-6 sticky top-0 z-[200] flex justify-between items-center shadow-2xl border-b border-white/5">
        <AppBrand />
        <button onClick={() => setIsMobileMenuOpen(true)} className="w-12 h-12 bg-white/5 rounded-2xl active:scale-90 transition-transform flex items-center justify-center">
          <span className="material-icons text-2xl">menu</span>
        </button>
      </header>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[300] md:hidden">
          <div className="absolute inset-0 bg-[#0f172a]/95 backdrop-blur-xl" onClick={() => setIsMobileMenuOpen(false)}></div>
          <div className="absolute top-0 right-0 bottom-0 w-[85%] bg-[#1e293b] shadow-2xl flex flex-col animate-fadeIn border-l border-white/5">
            <div className="p-8 flex justify-between items-center border-b border-white/5">
              <AppBrand />
              <button onClick={() => setIsMobileMenuOpen(false)} className="w-10 h-10 bg-white/5 rounded-full flex items-center justify-center text-white/20"><span className="material-icons">close</span></button>
            </div>
            <UserHeader />
            <nav className="flex-1 py-4 overflow-y-auto">
              {menuItems.map(item => (
                <button 
                  key={item.id} 
                  onClick={() => handleTabChange(item.id)} 
                  className={`w-full flex items-center justify-between px-10 py-6 border-b border-white/5 ${activeTab === item.id ? 'text-indigo-400 bg-white/5 font-black' : 'text-slate-400'}`}
                >
                  <div className="flex items-center gap-6">
                    <span className="material-icons text-2xl">{item.icon}</span>
                    <span className="text-[12px] font-black uppercase tracking-widest">{item.label}</span>
                  </div>
                  {item.id === 'new' && todaySpecial && (
                    <span className={`px-3 py-1 rounded-full bg-white/5 border border-white/10 text-[9px] font-black uppercase tracking-widest ${todaySpecial.color}`}>
                      {todaySpecial.name}
                    </span>
                  )}
                </button>
              ))}
            </nav>
          </div>
        </div>
      )}

      {showAuthModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#0f172a]/90 backdrop-blur-md" onClick={() => setShowAuthModal(false)} />
          <div className="relative w-full max-w-sm bg-[#1e293b] rounded-[3rem] p-10 shadow-2xl border border-white/10 animate-scaleUp">
            <div className="flex justify-between items-center mb-8">
               <h3 className="text-white font-black text-xl uppercase tracking-tighter">Login Cloud</h3>
               <button onClick={() => setShowAuthModal(false)} className="text-white/20"><span className="material-icons">close</span></button>
            </div>
            <AuthForm onSuccess={() => setShowAuthModal(false)} />
          </div>
        </div>
      )}

      <main className="flex-1 min-w-0">
        {isOffline && <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-2.5 text-center sticky top-0 z-[190] shadow-lg">Você está operando offline.</div>}
        <div className="px-4 py-10 md:p-16 animate-fadeIn max-w-4xl mx-auto">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} workers={customWorkers} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'learning' && <PraiseLearningList fullSongList={fullSongList} learningList={learningList} setLearningList={setLearningList} />}
          {activeTab === 'workers' && <WorkerRanking history={history} workers={customWorkers} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} workers={customWorkers} />}
          {activeTab === 'manage-workers' && <WorkerManager workers={customWorkers} setWorkers={setCustomWorkers} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={INITIAL_PRAISE_LIST} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} learningList={learningList} onRestore={(h, c, l) => { setHistory(h); setCustomSongs(c); setLearningList(l || []); }} onForceSync={() => user && pullFromCloud(user.id)} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] block mb-3 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-200 rounded-2xl px-4 py-1 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-500/50 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  workers: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, workers, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    let specialName = null;
    let specialColor = '';
    let specialEmoji = '';
    let specialBg = '';
    let specialBorder = '';
    let specialTextColor = '';

    if (dayIndex === 1) { 
      specialName = 'Glorificação'; 
      specialColor = 'bg-indigo-600'; 
      specialEmoji = '🎤';
      specialBg = 'bg-indigo-50/80';
      specialBorder = 'border-indigo-100';
      specialTextColor = 'text-indigo-700';
    }
    else if (dayIndex === 3) { 
      specialName = 'Senhoras'; 
      specialColor = 'bg-rose-500'; 
      specialEmoji = '🌸';
      specialBg = 'bg-rose-50/80';
      specialBorder = 'border-rose-100';
      specialTextColor = 'text-rose-700';
    }
    else if (dayIndex === 4) { 
      specialName = 'Oração'; 
      specialColor = 'bg-amber-500'; 
      specialEmoji = '🙏';
      specialBg = 'bg-amber-50/80';
      specialBorder = 'border-amber-100';
      specialTextColor = 'text-amber-700';
    }

    return { 
      name: dayOfWeekNames[dayIndex], 
      fullName: fullDayNames[dayIndex], 
      isSunday: dayIndex === 0, 
      isMonday: dayIndex === 1,
      isWednesday: dayIndex === 3,
      isThursday: dayIndex === 4,
      specialName,
      specialColor,
      specialEmoji,
      specialBg,
      specialBorder,
      specialTextColor
    };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleShareHinosOnly = () => {
    if (draft.songs.length === 0) return;
    const d = new Date(draft.date + 'T12:00:00');
    const dateStr = `${String(d.getDate()).padStart(2, '0')}/${String(d.getMonth() + 1).padStart(2, '0')}/${d.getFullYear()}`;
    const text = `🎶 *LISTA DE LOUVORES - ${dateStr}*\n\n` + 
      draft.songs.map((s, i) => `${i + 1}. ${s}`).join('\n');
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`);
  };

  const handleSave = () => {
    let finalDraft = { ...draft };
    if (dateInfo.isThursday) {
      finalDraft.roles.word = finalDraft.roles.praise;
    }
    onSave(finalDraft);
    setShowSuccessModal(true);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 1) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const isCiasA = a.startsWith('(CIAS)');
        const isCiasB = b.startsWith('(CIAS)');
        if (isCiasA !== isCiasB) return isCiasA ? 1 : -1;
        return a.localeCompare(b, undefined, { numeric: true });
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  const onDragStart = (item: string, index: number) => setDraggedIndex(index);
  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  return (
    <>
      {showSuccessModal && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm animate-fadeIn" onClick={() => setShowSuccessModal(false)} />
          <div className="relative bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center border border-slate-100">
            <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center mx-auto mb-6 text-white shadow-lg shadow-emerald-500/20">
              <span className="material-icons text-3xl">check</span>
            </div>
            <h3 className="text-xl font-black text-slate-900 mb-2 uppercase tracking-tighter">Relatório Salvo!</h3>
            <p className="text-slate-500 font-bold text-[10px] uppercase tracking-[0.2em] mb-10">Sincronizado na nuvem.</p>
            <button onClick={() => setShowSuccessModal(false)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-3xl shadow-xl active:scale-95 transition-all uppercase text-xs tracking-widest">OK, CONTINUAR</button>
          </div>
        </div>
      )}

      <div className="space-y-6 animate-fadeIn pb-20">
        <div className="section-header">
          <div className="flex items-center gap-4 mb-2">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <span className="material-icons text-xl">{editingId ? 'edit' : 'add_circle'}</span>
            </div>
            <h2 className="text-2xl font-black text-white uppercase tracking-tighter">{editingId ? 'Editar Relatório' : 'Novo Relatório'}</h2>
          </div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preencha os dados do culto</p>
        </div>

        <div className="card-main p-8 md:p-12">
          <div className="space-y-8">
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input type="date" value={draft.date} onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} className="w-full bg-transparent font-black text-lg text-slate-900 text-center outline-none py-2" />
                </FormInput>
                <div className="mt-3 flex flex-wrap gap-2 justify-center">
                  <div className="bg-indigo-50 px-4 py-1.5 rounded-full border border-indigo-100">
                    <span className="text-indigo-600 font-black text-[9px] uppercase tracking-[0.2em]">dia: {dateInfo.name}</span>
                  </div>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-200 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            <div className="space-y-4 pt-8 border-t border-slate-100">
              <div className="flex justify-between items-center">
